PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS el_organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'EGP',timezone TEXT NOT NULL DEFAULT 'Africa/Cairo',academic_year TEXT NOT NULL DEFAULT '2026/2027',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS el_branches(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),name TEXT NOT NULL,code TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',manager TEXT NOT NULL DEFAULT '',opening_hours TEXT NOT NULL DEFAULT '09:00–21:00',capacity INTEGER NOT NULL DEFAULT 100 CHECK(capacity>0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,code),UNIQUE(org_id,id));
CREATE TABLE IF NOT EXISTS el_users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS el_roles(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),name TEXT NOT NULL,system_key TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,name),UNIQUE(org_id,id));
CREATE TABLE IF NOT EXISTS el_role_permissions(role_id TEXT NOT NULL REFERENCES el_roles(id),resource TEXT NOT NULL,action TEXT NOT NULL,PRIMARY KEY(role_id,resource,action));
CREATE TABLE IF NOT EXISTS el_memberships(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),user_id TEXT NOT NULL REFERENCES el_users(id),role_id TEXT NOT NULL,branch_id TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id,role_id) REFERENCES el_roles(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),UNIQUE(org_id,user_id));
CREATE TABLE IF NOT EXISTS el_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES el_users(id),membership_id TEXT NOT NULL REFERENCES el_memberships(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,user_agent TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS el_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT,user_id TEXT NOT NULL REFERENCES el_users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,before_json TEXT,after_json TEXT,ip TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS el_login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,reset_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS el_branches_org ON el_branches(org_id,status);
CREATE INDEX IF NOT EXISTS el_memberships_user ON el_memberships(user_id,status);
CREATE INDEX IF NOT EXISTS el_audit_org ON el_audit(org_id,created_at);
CREATE INDEX IF NOT EXISTS el_sessions_exp ON el_sessions(expires_at);
